241	
242		embeddedDir := filepath.Join(getHasherAppDataDir(), "bin")
243		candidates = append(candidates,
244			filepath.Join(embeddedDir, "knirvhasher"),
245			filepath.Join(embeddedDir, "..", "bin", "knirvhasher"),
246		)
247	
248		candidates = append(candidates, configured)
249	
250		dir, _ := os.Getwd()
251		candidates = append(candidates,
252			filepath.Join(dir, "bin", "knirvhasher"),
253			filepath.Join(dir, "..", "bin", "knirvhasher"),
254		)
255	
256		for _, p := range candidates {
