269		ticker := time.NewTicker(500 * time.Millisecond)
270		defer ticker.Stop()
271	
272		for {
273			select {
274			case <-deadline.Done():
275				return fmt.Errorf("timeout waiting for KNIRVHASHER socket at %s", m.socketPath)
276			case <-ticker.C:
277				if _, err := os.Stat(m.socketPath); err == nil {
278					m.logger.Debug("KNIRVHASHER socket created at", zap.String("socket", m.socketPath))
279					return nil
280				}
281			}
282		}
283	}
