285	func (m *Manager) Stop(ctx context.Context) error {
286		m.mu.Lock()
287		defer m.mu.Unlock()
288	
289		if !m.running || m.cmd == nil || m.cmd.Process == nil {
290			return nil
291		}
292	
293		m.logger.Info("Stopping KNIRVHASHER")
294	
295		if err := m.cmd.Process.Signal(syscall.SIGTERM); err != nil {
296			m.logger.Warn("Failed to send SIGTERM, forcing kill",
297				zap.Error(err))
298			syscall.Kill(-m.cmd.Process.Pid, syscall.SIGKILL)
299		}
300	
301		done := make(chan error, 1)
302		go func() {
303			done <- m.cmd.Wait()
304		}()
305	
306		select {
307		case err := <-done:
308			m.running = false
309			m.startTime = time.Time{}
310			if err != nil {
311				m.logger.Info("KNIRVHASHER stopped", zap.Error(err))
312			} else {
313				m.logger.Info("KNIRVHASHER stopped gracefully")
314			}
315			return nil
316		case <-time.After(m.config.StopTimeout):
317			m.logger.Warn("Timeout waiting for graceful shutdown, forcing kill")
318			syscall.Kill(-m.cmd.Process.Pid, syscall.SIGKILL)
319			select {
320			case <-done:
321			case <-time.After(2 * time.Second):
322				m.logger.Warn("Wait() did not complete after Kill() — zombie possible")
323			}
324			m.running = false
325			m.startTime = time.Time{}
326			return fmt.Errorf("forced shutdown after timeout")
327		}
328	}
