353		defer m.mu.RUnlock()
354	
355		status := &HasherStatus{
356			Status:     "stopped",
357			Running:    m.running,
358			SocketPath: m.socketPath,
359			Timestamp:  time.Now(),
360		}
361		if m.running {
362			status.Status = "running"
363			if !m.startTime.IsZero() {
364				uptime := time.Since(m.startTime)
365				status.Uptime = uptime.Round(time.Second).String()
366			}
367		}
368	
369		return status
370	}
