372	func (m *Manager) triggerPipeline() {
373		client := &http.Client{
374			Timeout: 10 * time.Second,
375			Transport: &http.Transport{
376				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
377					var dialer net.Dialer
378					return dialer.DialContext(ctx, "unix", m.socketPath)
379				},
380			},
381		}
382	
383		pipelineURL := "http://localhost/api/v1/pipeline/run"
384		body := fmt.Sprintf(`{"type":"%s"}`, m.config.PipelineType)
385		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
386		if err != nil {
387			m.logger.Warn("Failed to create pipeline request", zap.Error(err))
388			return
389		}
390		req.Header.Set("Content-Type", "application/json")
391	
392		resp, err := client.Do(req)
393		if err != nil {
394			m.logger.Warn("Failed to trigger KNIRVHASHER data pipeline",
395				zap.String("socket", m.socketPath), zap.Error(err))
396			return
397		}
398		defer resp.Body.Close()
399	
400		if resp.StatusCode == http.StatusOK || resp.StatusCode == http.StatusAccepted {
401			m.logger.Info("KNIRVHASHER data pipeline triggered successfully",
402				zap.String("socket", m.socketPath),
403				zap.String("pipeline", m.config.PipelineType),
404				zap.Int("status", resp.StatusCode))
405		} else {
406			m.logger.Warn("KNIRVHASHER data pipeline trigger returned unexpected status",
407				zap.String("socket", m.socketPath),
408				zap.Int("status", resp.StatusCode))
409		}
410	}
411	
412	func (m *Manager) RunPipeline(pipelineType string) error {
413		if !m.running {
414			return fmt.Errorf("KNIRVHASHER not running")
415		}
416	
417		client := &http.Client{
418			Timeout: 30 * time.Second,
419			Transport: &http.Transport{
420				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
421				dialer := net.Dialer{}
422				return dialer.DialContext(ctx, "unix", m.socketPath)
423				},
424			},
425		}
426	
427		pipelineURL := "http://localhost/api/v1/pipeline/run"
428		body := fmt.Sprintf(`{"type":"%s"}`, pipelineType)
429		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
430		if err != nil {
431			return fmt.Errorf("failed to create request: %w", err)
432		}
433		req.Header.Set("Content-Type", "application/json")
434	
435		resp, err := client.Do(req)
436		if err != nil {
437			return fmt.Errorf("failed to trigger pipeline: %w", err)
438		}
439		defer resp.Body.Close()
440	
441		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusAccepted {
442			return fmt.Errorf("pipeline request failed with status %d", resp.StatusCode)
443		}
444	
445		return nil
446	}
447	
448	func (m *Manager) GetHealth() (bool, error) {
449		if !m.running {
450			return false, fmt.Errorf("KNIRVHASHER not running")
451		}
452	
453		client := &http.Client{
454			Timeout: 5 * time.Second,
455			Transport: &http.Transport{
456				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
457				dialer := net.Dialer{}
458				return dialer.DialContext(ctx, "unix", m.socketPath)
459				},
460			},
461		}
462	
463		resp, err := client.Get("http://localhost/api/v1/health")
464		if err != nil {
465			return false, err
466		}
467		defer resp.Body.Close()
468	
469		return resp.StatusCode == http.StatusOK, nil
470	}
471	
472	func (m *Manager) StopPipeline() error {
473		if !m.running {
474			return fmt.Errorf("KNIRVHASHER not running")
475		}
476	
477		client := &http.Client{
478			Timeout: 10 * time.Second,
479			Transport: &http.Transport{
480				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
481				dialer := net.Dialer{}
482				return dialer.DialContext(ctx, "unix", m.socketPath)
483				},
484			},
485		}
486	
487		resp, err := client.Post("http://localhost/api/v1/pipeline/stop", "application/json", nil)
488		if err != nil {
489			return fmt.Errorf("failed to stop pipeline: %w", err)
490		}
491		defer resp.Body.Close()
492	
493		return nil
494	}
495	
496	func isSocketReady(socketPath string) bool {
497		conn, err := net.Dial("unix", socketPath)
498		if err != nil {
499			return false
500		}
501		conn.Close()
502		return true
503	}

