14	// ── Background task ticker config ──────────────────────────────────────
15	
16	const TASK_TEMPLATES: { category: BackgroundTask['category']; labels: string[]; details: string[] }[] = [
17	  { category: 'workflow',   labels: ['Workflow Creation', 'Workflow Optimization'],          details: ['Assembling agentic pipeline from registered skills', 'Pruning redundant workflow nodes'] },
18	  { category: 'ontology',   labels: ['Ontology Organization', 'Concept Mapping'],            details: ['Reconciling knowledge graph ontology layers', 'Linking ContextNodes to capability embeddings'] },
19	  { category: 'error_node', labels: ['Error Node Resolution', 'ErrorNode Mining'],            details: ['Querying KNIRVGRAPH for unresolved error nodes', 'Proposing SkillNode candidate from error pattern'] },
20	  { category: 'dve_monitor',    labels: ['DVE Monitoring', 'DVE Health Scan'],                  details: ['Polling DVE heartbeat endpoints', 'Checking container resource utilization'] },
21	  { category: 'agent_monitor',  labels: ['Agent Monitoring', 'Agent Sync'],                     details: ['Verifying oh-my-pi agent responsiveness', 'Synchronizing agent state with orchestrator'] },
22	  { category: 'guardrails',     labels: ['Guardrails Report', 'Policy Validation'],             details: ['Running safety policy evaluation pass', 'Auditing output constraints against governance rules'] },
23	  { category: 'cache',          labels: ['Cache Allocation', 'Cache Eviction'],                 details: ['Rebalancing inference result cache buckets', 'Evicting stale embedding cache entries'] },
24	];
