26	const TASK_CATEGORY_ICONS: Record<BackgroundTask['category'], React.ReactNode> = {
27	  workflow: <GitBranch className="w-3 h-3" />,
28	  ontology: <BookOpen className="w-3 h-3" />,
29	  error_node: <Bug className="w-3 h-3" />,
30	  dve_monitor: <Server className="w-3 h-3" />,
31	  agent_monitor: <Bot className="w-3 h-3" />,
32	  guardrails: <Shield className="w-3 h-3" />,
33	  cache: <Database className="w-3 h-3" />,
34	};
35	
36	const TASK_STATUS_COLORS: Record<BackgroundTask['status'], string> = {
37	  running: 'text-blue-400',
38	  completed: 'text-green-400',
39	  failed: 'text-red-400',
40	  queued: 'text-yellow-400',
41	};
42	
43	let _taskCounter = 0;
44	function generateTask(forceCategory?: BackgroundTask['category']): BackgroundTask {
45	  const template = forceCategory
46	    ? TASK_TEMPLATES.find(t => t.category === forceCategory) ?? TASK_TEMPLATES[Math.floor(Math.random() * TASK_TEMPLATES.length)]
47	    : TASK_TEMPLATES[Math.floor(Math.random() * TASK_TEMPLATES.length)];
48	  const idx = Math.floor(Math.random() * template.labels.length);
49	  return {
50	    id: `task-${Date.now()}-${_taskCounter++}`,
51	    category: template.category,
52	    label: template.labels[idx],
53	    status: 'running',
54	    detail: template.details[idx],
55	    timestamp: Date.now(),
56	  };
57	}
