59	// ── Sub-component: KNIRVHASHER training controls ──────────────────────
60	
61	interface TrainingLog {
62	  id: string;
63	  timestamp: string;
64	  level: string;
65	  message: string;
66	}
67	
68	function HasherTrainingControls() {
69	  const [hasherStatus, setHasherStatus] = useState<'loading' | 'available' | 'unavailable'>('loading');
70	  const [trainingActive, setTrainingActive] = useState(false);
71	  const [trainingLogs, setTrainingLogs] = useState<TrainingLog[]>([]);
72	  const sseRef = useRef<EventSource | null>(null);
73	  const consoleRef = useRef<HTMLDivElement>(null);
74	  const logIdRef = useRef(0);
75	
76	  const fetchHasherStatus = async () => {
77	    try {
78	      const resp = await fetch(`${API_BASE_URL}/api/v1/hasher/status`);
79	      if (resp.ok) {
80	        const data = await resp.json();
81	        setHasherStatus(data.available ? 'available' : 'unavailable');
82	      } else {
83	        setHasherStatus('unavailable');
84	      }
85	    } catch {
86	      setHasherStatus('unavailable');
87	    }
88	  };
89	
90	  useEffect(() => {
91	    fetchHasherStatus();
92	    const interval = setInterval(fetchHasherStatus, 15000);
93	    return () => clearInterval(interval);
94	  }, []);
95	
96	  // Connect to KNIRVHASHER SSE log stream when training starts
97	  useEffect(() => {
98	    if (!trainingActive) {
99	      if (sseRef.current) {
100	        sseRef.current.close();
101	        sseRef.current = null;
102	      }
103	      return;
104	    }
105	
106	    // Close any previous connection
107	    if (sseRef.current) {
108	      sseRef.current.close();
109	    }
110	
111	    // 1. Pre-fill from history to get recent knirvhasher logs
112	    fetch(`${API_BASE_URL}/api/logs/history?module=knirvhasher&limit=100`)
113	      .then(r => r.json())
114	      .then(data => {
115	        const logs: { timestamp: string; level: string; message: string }[] = (data.logs || []).slice().reverse();
116	        setTrainingLogs(
117	          logs.map((l: any) => ({
118	            id: `log-${logIdRef.current++}`,
119	            timestamp: l.timestamp
120	              ? new Date(l.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
121	              : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
122	            level: l.level || 'info',
123	            message: l.message || '',
124	          }))
125	        );
126	      })
127	      .catch(() => { /* history pre-fill is best-effort */ });
128	
129	    // 2. Open SSE stream for live updates
130	    const es = new EventSource(`${API_BASE_URL}/api/logs/module/knirvhasher`);
131	    sseRef.current = es;
132	
133	    es.onmessage = (event) => {
134	      try {
135	        const data = JSON.parse(event.data);
136	        const ts = data.timestamp
137	          ? new Date(data.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
138	          : new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
139	        setTrainingLogs(prev => {
140	          const next = [...prev, {
141	            id: `log-${logIdRef.current++}`,
142	            timestamp: ts,
143	            level: data.level || 'info',
144	            message: data.message || '',
145	          }];
146	          return next.slice(-200); // keep last 200 lines
147	        });
148	      } catch {
149	        // ignore malformed events
150	      }
151	    };
152	
153	    es.onerror = () => {
154	      // SSE will auto-reconnect
155	    };
156	
157	    return () => {
158	      es.close();
159	      sseRef.current = null;
160	    };
161	  }, [trainingActive]);
162	
163	  // Auto-scroll console to bottom when new logs arrive
164	  useEffect(() => {
165	    if (consoleRef.current && trainingLogs.length > 0) {
166	      consoleRef.current.scrollTop = consoleRef.current.scrollHeight;
167	    }
168	  }, [trainingLogs]);
169	
170	  const clearTrainingLogs = () => {
171	    setTrainingLogs([]);
172	  };
173	
174	  const handleStartTraining = async () => {
175	    setTrainingActive(true);
176	    try {
177	      const resp = await fetch(`${API_BASE_URL}/api/v1/hasher/training/start`, {
178	        method: 'POST',
179	        headers: { 'Content-Type': 'application/json' },
180	      });
181	      if (!resp.ok) {
182	        setTrainingActive(false);
183	      }
184	    } catch {
185	      setTrainingActive(false);
186	    }
187	  };
188	
189	  const handleStopTraining = async () => {
190	    try {
191	      await fetch(`${API_BASE_URL}/api/v1/hasher/training/stop`, {
192	        method: 'POST',
193	        headers: { 'Content-Type': 'application/json' },
194	      });
195	    } catch { /* ignore */ }
196	    setTrainingActive(false);
197	  };
198	
199	  const statusColor = hasherStatus === 'available' ? 'bg-green-500' : 'bg-red-500';
200	  const statusLabel = hasherStatus === 'available' ? 'Available' : 'Unavailable';
201	
202	  const levelColor = (level: string) => {
203	    switch (level) {
204	      case 'error': return 'text-red-400';
205	      case 'warn': return 'text-yellow-400';
206	      case 'debug': return 'text-slate-500';
207	      default: return 'text-cyan-300';
208	    }
209	  };
210	
211	  const levelBadgeColor = (level: string) => {
212	    switch (level) {
213	      case 'error': return 'bg-red-900/50 text-red-300';
214	      case 'warn': return 'bg-yellow-900/50 text-yellow-300';
215	      case 'debug': return 'bg-slate-800 text-slate-400';
216	      default: return 'bg-cyan-900/50 text-cyan-300';
217	    }
218	  };
219	
220	  return (
221	    <div className="border-t border-indigo-900/30 pt-3 mt-3">
222	      <div className="flex items-center gap-2 mb-2">
223	        <Database className="w-4 h-4 text-cyan-400" />
224	        <span className="text-xs font-semibold text-cyan-300 uppercase tracking-wider">KNIRVHASHER Training</span>
225	        <div className="flex items-center gap-1.5 ml-auto">
226	          <div className={`w-2 h-2 rounded-full ${statusColor} ${hasherStatus === 'loading' ? 'animate-pulse' : ''}`} />
227	          <span className="text-xs text-slate-400">{hasherStatus === 'loading' ? 'Checking...' : statusLabel}</span>
228	        </div>
229	      </div>
230	
231	      {/* Console + Controls in flex row */}
232	      <div className="flex gap-3">
233	        {/* Left: Training Log Console */}
234	        <div className="flex-1 min-w-0">
235	          <div className="flex items-center justify-between mb-1">
236	            <div className="flex items-center gap-1.5">
237	              <Terminal className="w-3 h-3 text-slate-500" />
238	              <span className="text-[10px] font-medium text-slate-500 uppercase tracking-wider">
239	                {trainingActive ? 'Training Logs (knirvhasher)' : 'Training Console'}
240	              </span>
241	            </div>
242	            {trainingLogs.length > 0 && (
243	              <div className="flex items-center gap-2">
244	                <span className="text-[10px] text-slate-600">{trainingLogs.length} lines</span>
245	                <button
246	                  onClick={clearTrainingLogs}
247	                  className="text-[10px] text-slate-600 hover:text-slate-300 transition-colors"
248	                >
249	                  Clear
250	                </button>
251	              </div>
252	            )}
253	          </div>
254	          <div
255	            ref={consoleRef}
256	            className="h-36 overflow-y-auto rounded-md border border-border/20 bg-black/50 p-2 font-mono text-[11px] leading-relaxed"
257	          >
258	            {trainingLogs.length === 0 && (
259	              <div className="text-slate-600 text-center py-8">
260	                {trainingActive
261	                  ? 'Waiting for training logs...'
262	                  : 'Start training to view pipeline logs'}
263	              </div>
264	            )}
265	            {trainingLogs.map((log) => (
266	              <div key={log.id} className="flex items-start gap-1.5 py-px hover:bg-white/[0.02]">
267	                <span className="text-slate-600 shrink-0 w-16 text-right">{log.timestamp}</span>
268	                <span className={`shrink-0 px-1 rounded text-[9px] font-semibold uppercase ${levelBadgeColor(log.level)}`}>
269	                  {log.level}
270	                </span>
271	                <span className={`${levelColor(log.level)} break-all`}>{log.message}</span>
272	              </div>
273	            ))}
274	          </div>
275	        </div>
276	
277	        {/* Right: Training Controls */}
278	        <div className="shrink-0 flex flex-col gap-2 justify-start pt-6">
279	          <Button
280	            variant={trainingActive ? 'secondary' : 'default'}
281	            size="sm"
282	            onClick={handleStartTraining}
283	            disabled={hasherStatus !== 'available' || trainingActive}
284	          >
285	            <Play className="w-4 h-4 mr-2" />
286	            Start Training
287	          </Button>
288	          <Button
289	            variant={trainingActive ? 'destructive' : 'secondary'}
290	            size="sm"
291	            onClick={handleStopTraining}
292	            disabled={!trainingActive}
293	          >
294	            <Square className="w-4 h-4 mr-2" />
295	            Stop Training
296	          </Button>
297	          <Button variant="outline" size="sm" onClick={fetchHasherStatus}>
298	            <RefreshCw className="w-4 h-4 mr-2" />
299	            Refresh Status
300	          </Button>
301	        </div>
302	      </div>
303	
304	      {trainingActive && (
305	        <div className="flex items-center gap-2 mt-2 text-xs text-cyan-400">
306	          <Loader2 className="w-3 h-3 animate-spin" />
307	          Training pipeline active
308	        </div>
309	      )}
310	    </div>
311	  );
312	}
