314	// ── Sub-component: Cognitive Engine Status Card ───────────────────────
315	
316	export function CognitiveEngineStatusCard({ className }: { className?: string }) {
317	  const {
318	    cognitiveEngine,
319	    isLoading,
320	  } = useCognitiveEngine();
321	
322	  const [showTaskStatus, setShowTaskStatus] = useState(true);
323	  const [rollingLog, setRollingLog] = useState<BackgroundTask[]>([]);
324	
325	  // Rolling background task log
326	  useEffect(() => {
327	    const isActive = cognitiveEngine?.status === 'active' || cognitiveEngine?.status === 'learning';
328	    if (!isActive) return;
329	
330	    if (cognitiveEngine?.background_tasks?.length) {
331	      setRollingLog(prev => [...cognitiveEngine.background_tasks!, ...prev].slice(0, 80));
332	    }
333	
334	    const interval = setInterval(() => {
335	      const newTask = generateTask();
336	      setRollingLog(prev => {
337	        const updated = prev.map(t =>
338	          t.status === 'running' && Math.random() > 0.4 ? { ...t, status: 'completed' as const } : t
339	        );
340	        return [newTask, ...updated].slice(0, 80);
341	      });
342	    }, 3500 + Math.random() * 2500);
343	
344	    return () => clearInterval(interval);
345	  }, [cognitiveEngine?.status, cognitiveEngine?.background_tasks]);
346	
347	  const getStatusColor = (status: string) => {
348	    switch (status) {
349	      case 'active': return 'bg-green-500';
350	      case 'learning': return 'bg-blue-500';
351	      case 'idle': return 'bg-yellow-500';
352	      case 'error': return 'bg-red-500';
353	      case 'degraded': return 'bg-orange-500';
354	      case 'stopped': return 'bg-gray-500';
355	      default: return 'bg-gray-500';
356	    }
357	  };
358	
359	  const getStatusIcon = (status: string) => {
360	    switch (status) {
361	      case 'active': return <CheckCircle className="w-4 h-4" />;
362	      case 'learning': return <Activity className="w-4 h-4" />;
363	      case 'idle': return <Clock className="w-4 h-4" />;
364	      case 'error': return <AlertCircle className="w-4 h-4" />;
365	      case 'degraded': return <AlertCircle className="w-4 h-4" />;
366	      case 'stopped': return <Square className="w-4 h-4" />;
367	      default: return <Brain className="w-4 h-4" />;
368	    }
369	  };
370	
371	  const formatUptime = (seconds: number) => {
372	    const days = Math.floor(seconds / 86400);
373	    const hours = Math.floor((seconds % 86400) / 3600);
374	    const minutes = Math.floor((seconds % 3600) / 60);
375	    if (days > 0) return `${days}d ${hours}h`;
376	    if (hours > 0) return `${hours}h ${minutes}m`;
377	    return `${minutes}m`;
378	  };
379	
380	  return (
381	    <Card className={`knirv-card-gradient ${className || ''}`}>
382	      <CardHeader>
383	        <CardTitle className="flex items-center justify-between">
384	          <div className="flex items-center space-x-2">
385	            <Brain className="w-5 h-5" />
386	            <span>Cognitive Engine Status</span>
387	          </div>
388	          <div className="flex items-center space-x-2">
389	            <Badge
390	              variant="secondary"
391	              className={`${cognitiveEngine ? getStatusColor(cognitiveEngine.status) : 'bg-gray-500'} text-white`}
392	            >
393	              <div className="flex items-center space-x-1">
394	                {cognitiveEngine ? getStatusIcon(cognitiveEngine.status) : <Brain className="w-4 h-4" />}
395	                <span>{cognitiveEngine?.status || 'Unknown'}</span>
396	              </div>
397	            </Badge>
398	          </div>
399	        </CardTitle>
400	        <CardDescription>
401	          Fabric Version: {cognitiveEngine?.model_version || 'Loading...'}
402	        </CardDescription>
403	      </CardHeader>
404	      <CardContent>
405	        {/* Core Metrics */}
406	        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
407	          <div className="text-center p-3 bg-gray-900/30 rounded-lg">
408	            <div className="text-2xl font-bold text-primary">
409	              {cognitiveEngine?.accuracy.toFixed(1) || '--'}%
410	            </div>
411	            <div className="text-xs text-muted-foreground">Accuracy</div>
412	          </div>
413	          <div className="text-center p-3 bg-gray-900/30 rounded-lg">
414	            <div className="text-2xl font-bold text-primary">
415	              {cognitiveEngine?.tasks_processed.toLocaleString() || '--'}
416	            </div>
417	            <div className="text-xs text-muted-foreground">Tasks Processed</div>
418	          </div>
419	          <div className="text-center p-3 bg-gray-900/30 rounded-lg">
420	            <div className="text-2xl font-bold text-primary">
421	              {cognitiveEngine ? (cognitiveEngine.adaptation_rate * 100).toFixed(0) : '--'}%
422	            </div>
423	            <div className="text-xs text-muted-foreground">Adaptation Rate</div>
424	          </div>
425	          <div className="text-center p-3 bg-gray-900/30 rounded-lg">
426	            <div className="text-2xl font-bold text-primary">
427	              {cognitiveEngine ? formatUptime(cognitiveEngine.uptime) : '--'}
428	            </div>
429	            <div className="text-xs text-muted-foreground">Uptime</div>
430	          </div>
431	        </div>
432	
433	        {/* Performance and Learning Metrics */}
434	        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
435	          <Card className="knirv-card-gradient bg-gray-900/20">
436	            <CardHeader className="pb-2">
437	              <CardTitle className="flex items-center space-x-2 text-sm">
438	                <Cpu className="w-4 h-4" />
439	                <span>Performance Metrics</span>
440	              </CardTitle>
441	            </CardHeader>
442	            <CardContent>
443	              <div className="space-y-2">
444	                <div className="flex justify-between items-center">
445	                  <span className="text-xs">Inference Latency:</span>
446	                  <span className="text-xs font-medium">{cognitiveEngine?.performance_metrics?.inference_latency?.toFixed(1) || '--'}ms</span>
447	                </div>
448	                <div className="flex justify-between items-center">
449	                  <span className="text-xs">Throughput:</span>
450	                  <span className="text-xs font-medium">{cognitiveEngine?.performance_metrics?.throughput?.toLocaleString() || '--'} req/s</span>
451	                </div>
452	                <div className="flex justify-between items-center">
453	                  <span className="text-xs">Error Rate:</span>
