594	    const hours = Math.floor((seconds % 86400) / 3600);
595	    const minutes = Math.floor((seconds % 3600) / 60);
596	    if (days > 0) return `${days}d ${hours}h`;
597	    if (hours > 0) return `${hours}h ${minutes}m`;
598	    return `${minutes}m`;
