627	          <CardTitle className="flex items-center space-x-2">
628	            <Zap className="w-5 h-5" />
629	            <span>Engine Controls</span>
630	          </CardTitle>
631	        </CardHeader>
632	        <CardContent>
633	          {/* Cognitive Engine Buttons */}
634	          <div className="flex flex-wrap gap-2">
635	            <Button
636	              variant={cognitiveEngine?.status === 'active' ? 'secondary' : 'default'}
637	              size="sm"
638	              onClick={startEngine}
639	              disabled={isLoading || cognitiveEngine?.status === 'active'}
640	            >
641	              <Play className="w-4 h-4 mr-2" />
642	              Start Engine
643	            </Button>
644	            <Button
645	              variant={cognitiveEngine?.status === 'active' ? 'destructive' : 'secondary'}
646	              size="sm"
647	              onClick={stopEngine}
648	              disabled={isLoading || cognitiveEngine?.status !== 'active'}
649	            >
650	              <Square className="w-4 h-4 mr-2" />
651	              Stop Engine
652	            </Button>
653	            <Button variant="outline" size="sm" onClick={() => { healthCheck().then((success) => { setHealthResult(success ? 'Healthy' : 'Unhealthy'); setTimeout(() => setHealthResult(null), 5000); }); }} disabled={isLoading}>
654	              <Heart className="w-4 h-4 mr-2" />
655	              Health Check
