662	              {showTaskStatus ? <EyeOff className="w-4 h-4 mr-2" /> : <Eye className="w-4 h-4 mr-2" />}
663	              {showTaskStatus ? 'Hide Status' : 'Show Status'}
664	            </Button>
665	            <Button variant="outline" size="sm" onClick={resetMetrics} disabled={isLoading}>
666	              Reset Metrics
667	            </Button>
668	            <Button variant="outline" size="sm" onClick={clearConversationHistory} disabled={isLoading}>
669	              Clear History
