671	            {/* Engine status quick stat */}
672	            <div className="flex items-center gap-2 ml-auto">
673	              <Badge variant="outline" className="text-xs">
674	                <Activity className="w-3 h-3 mr-1" />
675	                {cognitiveEngine?.status || 'unknown'}
