2	
3	import (
4		"fmt"
5		"io"
6		"os"
7		"sync"
8	
9		ws "backend_server/internal/services/websocket"
10	)
11	
12	var logHandler *ws.LogStreamHandler
13	
14	func SetLogStreamHandler(h *ws.LogStreamHandler) {
15		logHandler = h
16	}
17	
18	func getLogHandler() *ws.LogStreamHandler {
19		return logHandler
20	}
21	
22	func EmitModuleLog(module, level, message string) {
23		if logHandler != nil {
24			logHandler.EmitLog(module, level, message, "backend_server", nil)
25			return
26		}
27		if wsHandler := ws.GetLogStreamHandler(); wsHandler != nil {
28			wsHandler.EmitLog(module, level, message, "backend_server", nil)
29		}
30	}
31	
32	type ModuleLogger interface {
33		EmitLog(level, msg string)
34		GetModuleName() string
35	}
36	
37	type LogEmitter struct {
38		mu        sync.Mutex
39		module    string
40		logWriter io.Writer
41		original  io.Writer
42	}
43	
44	func NewLogEmitter(module string, writer io.Writer) *LogEmitter {
45		return &LogEmitter{
46			module:    module,
47			logWriter: writer,
48			original:  writer,
49		}
50	}
51	
52	func (le *LogEmitter) StartCapture() {
53		le.mu.Lock()
54		defer le.mu.Unlock()
55		if le.logWriter == nil {
56			return
57		}
58		le.original = le.logWriter
59		le.logWriter = &logPrefixWriter{
60			module: le.module,
61			parent: le.original,
62		}
63	}
64	
65	func (le *LogEmitter) StopCapture() {
66		le.mu.Lock()
67		defer le.mu.Unlock()
68		if le.logWriter != nil {
69			le.logWriter = le.original
70		}
71	}
72	
73	func (le *LogEmitter) GetWriter() io.Writer {
74		le.mu.Lock()
75		defer le.mu.Unlock()
76		return le.logWriter
77	}
78	
79	type logPrefixWriter struct {
80		module string
81		parent io.Writer
82	}
83	
84	func (lw *logPrefixWriter) Write(p []byte) (n int, err error) {
85		line := string(p)
86		if len(line) > 0 && line[len(line)-1] == '\n' {
87			line = line[:len(line)-1]
88		}
89		prefixed := fmt.Sprintf("[%s] %s\n", lw.module, line)
90		return lw.parent.Write([]byte(prefixed))
91	}
92	
93	var logEmitters = make(map[string]*LogEmitter)
94	var logEmitterMu sync.Mutex
95	
96	func GetLogEmitter(module string) *LogEmitter {
97		logEmitterMu.Lock()
98		defer logEmitterMu.Unlock()
